import {MOBILE_BOX_VARIANTS} from './mobileSurfaceManifest.js';
import {VisualChapter} from './mobileVisualFlow.js';
import {TABS} from '@openisd/design/chart';
import {PHONE_FILTER_CHIPS} from '@openisd/design/fields';
export enum DesktopRoute {Bin='bin',ProjectActions='project-actions',InfoMenu='info-menu',Cloud='cloud',Chart='chart',ChartPicker='chart-picker',ChartData='chart-data',Box='box',Enclosure='enclosure',Losses='losses',Tab='tab',Editor='editor',Options='options',Info='info',Library='library',Picker='picker',WhatIf='what-if',Filter='filter',Wizard='wizard',Projects='projects',ProjectImport='project-import',ProjectExport='project-export',DriverImport='driver-import',DriverExport='driver-export',DriverSave='driver-save'}
export interface DesktopSurface {id:string;title:string;chapter:VisualChapter;group:string;owner:string;route:DesktopRoute;root:string;parameter?:string;box?:string;chamber?:string;relatedMobileIds:string[];relationship:string}
const original='packages/ui/src/ui/shells/original/',shared='packages/ui/src/ui/components/';
const rows:DesktopSurface[]=[];
const boxKeys:Record<string,string>={sealed:'closed-box',vented:'vented','box-passive-radiator':'passive-radiator',bandpass4:'bandpass-4th-order',bandpass6:'bandpass-6th-order',abc:'abc'};
function add(id:string,title:string,chapter:VisualChapter,group:string,route:DesktopRoute,root:string,relatedMobileIds:string[],extra:Partial<DesktopSurface>={}):void{rows.push({id:'desktop/'+id,title,chapter,group,route,root,owner:original+'OriginalShell.vue',relatedMobileIds,relationship:'Related task; desktop layout is independently captured.',...extra});}
for(const box of MOBILE_BOX_VARIANTS){
 const key=boxKeys[box];
 add('enclosure/'+key+'/box-tab',key+' — Box tab',VisualChapter.Views,key,DesktopRoute.Box,'.tab-section.active',['box-'+box],{box,relationship:'Desktop Box tab: the mobile Box page also contains controls from the separate desktop enclosure tab.'});
 if(box!=='sealed')add('enclosure/'+key+'/'+(box==='box-passive-radiator'?'radiator-tab':'vents-tab'),key+' — '+(box==='box-passive-radiator'?'Passive Radiator':'Vents')+' tab',VisualChapter.Views,key,DesktopRoute.Enclosure,'.tab-section.active',['box-'+box],{box,relationship:'Separate desktop enclosure-controls tab; these controls appear within the mobile Box page.'});
 for(const chamber of ['bandpass4','bandpass6','abc'].includes(box)?['Rear','Front']:['Rear'])add('enclosure/'+key+'/losses/'+chamber.toLowerCase(),key+' — '+chamber+' chamber losses',VisualChapter.Views,key,DesktopRoute.Losses,'.overlay.open .modal',['losses-'+box+'-'+chamber],{box,chamber});
 add('results/what-if/'+key,'What-if — '+key,VisualChapter.Views,'What-if',DesktopRoute.WhatIf,'.what-if-panel',['what-if-'+box],{box,owner:original+'OriginalWhatIf.vue',relationship:'Desktop What-if is a persistent panel beside the workspace; mobile uses a sheet over the Graph page.'});
 for(const [index,step] of ['choose-driver','driver-array','enclosure-type','enclosure-details','project-details'].entries())add('projects/new/'+key+'/'+step,'New '+key+' project — '+step.replaceAll('-',' '),VisualChapter.Wizard,key,DesktopRoute.Wizard,'.overlay.open .modal',['wizard-'+box+'-'+(index+1)],{box,parameter:String(index+1),owner:original+'OriginalNewProject.vue'});
}
for(const [tab,related,chapter] of [['Driver','tab-driver',VisualChapter.Views],['Signal','tab-signal',VisualChapter.Views],['Filters','tab-filters',VisualChapter.Views],['Advanced','menu-advanced',VisualChapter.Settings],['Project','menu-project-details',VisualChapter.Projects]] as const)add('workspace/'+tab.toLowerCase(),tab+' tab with adjacent graph',chapter,tab,DesktopRoute.Tab,'.tab-section.active',[related],{parameter:tab,relationship:'Desktop tab and graph share the workspace; the related mobile view occupies a separate page or dialog.'});
for(const tab of ['General','Parameters','Advanced','Dimensions'])add('driver/editor/'+tab.toLowerCase(),'Driver Editor — '+tab,VisualChapter.Drivers,'Driver Editor',DesktopRoute.Editor,'.de-modal',['editor-'+tab.toLowerCase()],{parameter:tab,owner:shared+'DriverEditorModal.vue'});
for(const tab of ['General','Plot Window','Your data'])add('settings/options/'+tab.toLowerCase().replaceAll(' ','-'),'Options — '+tab,VisualChapter.Settings,'Options',DesktopRoute.Options,'.opt-modal',['options-'+tab.toLowerCase().replaceAll(' ','-')],{parameter:tab,owner:shared+'OptionsModal.vue'});
for(const [name,related,root] of [['About OpenISD','menu-splashmodal','.sp'],['Diagnostics','menu-diagnosticsmodal','.dg'],['Announcements','menu-announcementsmodal','.ann-modal'],['OpenISD and WinISD differences','menu-winisddifferencesmodal','.wd-modal']])add('help/'+(name==='About OpenISD'?'about':name==='OpenISD and WinISD differences'?'differences':name.toLowerCase()),name,VisualChapter.Help,name,DesktopRoute.Info,root,[related],{parameter:name});
add('driver/library/overview','Manage Drivers — library',VisualChapter.Drivers,'Driver library',DesktopRoute.Library,'.wb-modal',['menu-manage-drivers'],{owner:shared+'DriverBrowser.vue'});
add('driver/project/select','Select driver for project',VisualChapter.Views,'Project driver',DesktopRoute.Picker,'.wb-modal',['driver-picker'],{owner:shared+'DriverBrowser.vue'});
add('projects/library/overview','Projects panel beside the graph',VisualChapter.Projects,'Project library',DesktopRoute.Projects,'.original-project-list',['menu-projects'],{owner:original+'OriginalProjectList.vue',relationship:'An embedded desktop panel; mobile uses its Projects dialog.'});
add('projects/import/file','Project Import — app entry point',VisualChapter.Projects,'Project Import',DesktopRoute.ProjectImport,'.original-project-list',['project-import'],{owner:original+'OriginalProjectList.vue',relationship:'Import is an action. Its following file picker belongs to the OS, and is not pictured by the app screenshot.'});
add('projects/export/formats','Project Export — formats menu',VisualChapter.Projects,'Project Export',DesktopRoute.ProjectExport,'.export-menu-list',['exports'],{owner:shared+'ExportMenu.vue'});
add('driver/import/file','Driver Import — app entry point',VisualChapter.Drivers,'Driver Import',DesktopRoute.DriverImport,'.de-modal',['driver-import'],{owner:shared+'DriverEditorModal.vue',relationship:'Import is an action. Its following file picker belongs to the OS.'});
add('driver/export/format','Driver Export — choose format',VisualChapter.Drivers,'Driver Export',DesktopRoute.DriverExport,'.fmt-panel',['driver-export'],{owner:shared+'DriverEditorModal.vue'});
add('driver/library/save','Save to My Drivers',VisualChapter.Drivers,'Driver library',DesktopRoute.DriverSave,'[role=dialog]',['driver-save'],{owner:shared+'SaveToLibraryDialog.vue'});
for(const filter of PHONE_FILTER_CHIPS)add('signal/filters/'+filter.type.replace(/([a-z])([A-Z])/g,'$1-$2').toLowerCase(),filter.short+' inline editor',VisualChapter.Views,'Filters',DesktopRoute.Filter,'.filter-row-inline.editing',['filter-'+filter.type],{parameter:'+ '+filter.short,owner:original+'OriginalFilters.vue'});
for(const chart of TABS)add('results/charts/'+chart.id.replace(/([a-z])([A-Z])/g,'$1-$2').toLowerCase(),chart.name+' — graph region',VisualChapter.Views,'Graph and charts',DesktopRoute.Chart,'.graph-area',['chart-'+chart.id],{parameter:chart.id,relationship:'An embedded graph region beside the desktop tabs; mobile opens its own Graph page. This is a chart state, not a separate desktop page.'});
add('results/charts/choose','Chart selection menu',VisualChapter.Views,'Graph and charts',DesktopRoute.ChartPicker,'.chart-select .dropdown-menu.open',['chart-picker']);
add('results/charts/data-table','Chart data dialog',VisualChapter.Views,'Graph and charts',DesktopRoute.ChartData,'[role=dialog]',['chart-data'],{owner:shared+'ChartDataDialog.vue'});
add('projects/library/bin','Project Bin',VisualChapter.Projects,'Project library',DesktopRoute.Bin,'.original-project-list',['bin'],{owner:original+'OriginalProjectList.vue'});
add('projects/library/actions','Project actions menu',VisualChapter.Projects,'Project library',DesktopRoute.ProjectActions,'.row-menu-popup',['project-actions'],{owner:original+'OriginalProjectList.vue'});
add('navigation/info-menu','Info menu',VisualChapter.Shared,'Info menu',DesktopRoute.InfoMenu,'.tb-menu .dropdown-menu.open',['menu'],{relationship:'The desktop Info menu corresponds to only the help/app portion of the mobile main menu, not the whole menu.'});
add('settings/cloud/account-and-activity','Cloud account and activity',VisualChapter.Settings,'Cloud',DesktopRoute.Cloud,'.cloud-modal',['cloud'],{owner:shared+'CloudSyncDialog.vue'});
export const DESKTOP_SURFACES:readonly DesktopSurface[]=Object.freeze(rows);
